describe("Autocomplete Async",function(){var b=document.createElement("input"),a,d=false,c=new $.Autocomplete(b,{serviceUrl:"/test",onSearchStart:function(e){a=e.query}});beforeEach(function(e){$.mockjax({url:"/test",responseTime:50,response:function(g){d=true;var h=g.data.query,f={query:h,suggestions:[]};this.responseText=JSON.stringify(f);e()}});b.value="A";c.onValueChange()});it("Should execute onSearchStart",function(){expect(d).toBe(true);expect(a).toBe("A")})});describe("Autocomplete Async",function(){var a=document.createElement("input"),c,f={value:"A",data:"A"},d,e=false,b="/test-completed";beforeEach(function(g){var h=new $.Autocomplete(a,{serviceUrl:b,onSearchComplete:function(j,i){c=j;d=i;g()}});$.mockjax({url:b,responseTime:50,response:function(j){e=true;var k=j.data.query,i={query:k,suggestions:[f]};this.responseText=JSON.stringify(i)}});a.value="A";h.onValueChange()});it("Should execute onSearchComplete",function(){expect(e).toBe(true);expect(c).toBe("A");expect(d[0].value).toBe("A");expect(d[0].data).toBe("A")})});describe("Autocomplete Async",function(){var a=false;beforeEach(function(b){var c=document.createElement("input"),d="/test-error",e=new $.Autocomplete(c,{serviceUrl:d,onSearchError:function(g,f,i,h){a=f.responseText;b()}});$.mockjax({url:d,responseTime:50,status:500,response:function(f){this.responseText="An error occurred"}});c.value="A";e.onValueChange()});it("Should execute onSearchError",function(){expect(a).toBe("An error occurred")})});describe("Asyn",function(){var a;beforeEach(function(b){var c=document.createElement("input"),f=false,d="/test-transform",e=new $.Autocomplete(c,{serviceUrl:d,transformResult:function(g,h){setTimeout(b,0);return{query:h,suggestions:$.map(g.split(","),function(i){return{value:i,data:null}})}}});$.mockjax({url:d,responseTime:50,response:function(){f=true;this.responseText="Andora,Angola,Argentina"}});a=e;c.value="A";e.onValueChange()});it("Should transform results",function(){expect(a.suggestions.length).toBe(3);expect(a.suggestions[0].value).toBe("Andora")})});describe("Autocomplete Async",function(){var a;beforeEach(function(b){var c=document.createElement("input"),f=false,d="/test-original-query",e=new $.Autocomplete(c,{serviceUrl:d});$.mockjax({url:d,responseTime:50,response:function(){f=true;var g={query:null,suggestions:["Aa","Bb","Cc"]};this.responseText=JSON.stringify(g);setTimeout(b,0)}});c.value="A";a=e;e.onValueChange()});it("Should not require orginal query value from the server",function(){expect(a.suggestions.length).toBe(3);expect(a.suggestions[0].value).toBe("Aa")})});describe("Autocomplete Async",function(){var a;beforeEach(function(b){var c=document.createElement("input"),e="custom",d=new $.Autocomplete(c,{serviceUrl:"/test-query",paramName:e});$.mockjax({url:"/test-query",responseTime:5,response:function(g){a=g.data[e];var f={query:a,suggestions:[]};this.responseText=JSON.stringify(f);b()}});c.value="Jam";d.onValueChange()});it("Should use custom query parameter name",function(){expect(a).toBe("Jam")})});describe("Autocomplete Async",function(){var a,b;beforeEach(function(c){var d=$(document.createElement("input"));d.autocomplete({ignoreParams:true,serviceUrl:function(e){return"/dynamic-url/"+encodeURIComponent(e).replace(/%20/g,"+")}});$.mockjax({url:"/dynamic-url/*",responseTime:5,response:function(f){a=f.url;b=f.data;var e={suggestions:[]};this.responseText=JSON.stringify(e);c()}});d.val("Hello World");d.autocomplete().onValueChange()});it("Should construct serviceUrl via callback function.",function(){expect(a).toBe("/dynamic-url/Hello+World");expect(b).toBeFalsy()})});describe("Autocomplete Async",function(){var a,b;beforeEach(function(c){var d=$("<input />"),g=false,e={a:1,query:"Jam"},f="/autocomplete/cached/url";b=f+"?"+$.param(e);d.autocomplete({serviceUrl:f,params:e});$.mockjax({url:f,responseTime:5,response:function(i){g=true;var j=i.data.query,h={suggestions:[{value:"Jamaica"},{value:"Jamaica"}]};this.responseText=JSON.stringify(h);setTimeout(c,10)}});d.val("Jam");a=d.autocomplete();a.onValueChange()});it("Should use serviceUrl and params as cacheKey",function(){expect(a.cachedResponse[b]).toBeTruthy()})});describe("Autocomplete Async",function(){var a=0;beforeEach(function(c){var d=$("<input />"),b,e="/autocomplete/prevent/ajax";d.autocomplete({serviceUrl:e});$.mockjax({url:e,responseTime:1,response:function(g){a+=1;var f={suggestions:[]};this.responseText=JSON.stringify(f);if(a===2){c()}}});setTimeout(function(){d.val("Jam");b=d.autocomplete();b.onValueChange()},10);setTimeout(function(){d.val("Jama");b.onValueChange()},20);setTimeout(function(){b.setOptions({preventBadQueries:false});d.val("Jamai");b.onValueChange()},30)});it("Should prevent Ajax requests if previous query with matching root failed.",function(){expect(a).toBe(2)})});describe("Autocomplete",function(){afterEach(function(){$(".autocomplete-suggestions").hide()});it("Should initialize autocomplete options",function(){var a=document.createElement("input"),b={serviceUrl:"/autocomplete/service/url"},c=new $.Autocomplete(a,b);expect(c.options.serviceUrl).toEqual(b.serviceUrl);expect(c.suggestionsContainer).not.toBeNull()});it('Should set autocomplete attribute to "off"',function(){var a=document.createElement("input"),b=new $.Autocomplete(a,{});expect(b).not.toBeNull();expect(a.getAttribute("autocomplete")).toEqual("off")});it("Should get current value",function(){var a=document.createElement("input"),b=new $.Autocomplete(a,{lookup:[{value:"Jamaica",data:"B"}]});a.value="Jam";b.onValueChange();expect(b.visible).toBe(true);expect(b.currentValue).toEqual("Jam")});it("Should call formatResult three times",function(){var c=document.createElement("input"),a=0,b,d,e=new $.Autocomplete(c,{lookup:["Jamaica","Jamaica","Jamaica"],formatResult:function(g,f){b=g;d=f;a+=1}});c.value="Jam";e.onValueChange();expect(b.value).toBe("Jamaica");expect(b.data).toBe(null);expect(d).toEqual("Jam");expect(a).toEqual(3)});it("Verify onSelect callback",function(){var a=document.createElement("input"),b,e,d,c=$(a).autocomplete({lookup:[{value:"A",data:"B"}],triggerSelectOnValidInput:false,onSelect:function(f){b=this;e=f.value;d=f.data}}).autocomplete();a.value="A";c.onValueChange();c.select(0);expect(b).toEqual(a);expect(e).toEqual("A");expect(d).toEqual("B")});it("Should convert suggestions format",function(){var a=document.createElement("input"),b=new $.Autocomplete(a,{lookup:["A","B"]});expect(b.options.lookup[0].value).toBe("A");expect(b.options.lookup[1].value).toBe("B")});it("Should should not preventDefault when tabDisabled is set to false",function(){var a=document.createElement("input"),c=new $.Autocomplete(a,{lookup:[{value:"Jamaica",data:"B"}],tabDisabled:false,autoSelectFirst:true});a.value="Jam";c.onValueChange();var b=$.Event("keydown");b.which=9;spyOn(b,"stopImmediatePropagation");spyOn(b,"preventDefault");spyOn(c,"suggest");expect(c.visible).toBe(true);expect(c.disabled).toBe(undefined);expect(c.selectedIndex).not.toBe(-1);$(a).trigger(b);expect(b.stopImmediatePropagation).not.toHaveBeenCalled();expect(b.preventDefault).not.toHaveBeenCalled();expect(c.suggest).not.toHaveBeenCalled()});it("Should should preventDefault when tabDisabled is set to true",function(){var a=document.createElement("input"),c=new $.Autocomplete(a,{lookup:[{value:"Jamaica",data:"B"}],tabDisabled:true,autoSelectFirst:true});a.value="Jam";c.onValueChange();var b=$.Event("keydown");b.which=9;spyOn(c,"suggest");expect(c.visible).toBe(true);expect(c.disabled).toBe(undefined);expect(c.selectedIndex).not.toBe(-1);$(a).trigger(b);expect(c.suggest).not.toHaveBeenCalled()});it("Should not autoselect first item by default",function(){var a=document.createElement("input"),b=new $.Autocomplete(a,{lookup:["Jamaica","Jamaica","Jamaica"]});a.value="Jam";b.onValueChange();expect(b.selectedIndex).toBe(-1)});it("Should autoselect first item autoSelectFirst set to true",function(){var a=document.createElement("input"),b=new $.Autocomplete(a,{lookup:["Jamaica","Jamaica","Jamaica"],autoSelectFirst:true});a.value="Jam";b.onValueChange();expect(b.selectedIndex).toBe(0)});it("Should destroy autocomplete instance",function(){var a=$(document.createElement("input")),b=$(document.createElement("div"));a.autocomplete({serviceUrl:"/test-dispose",appendTo:b});expect(a.data("autocomplete")).toBeDefined();expect(b.children().length).toBeGreaterThan(0);a.autocomplete("dispose");expect(a.data("autocomplete")).toBeUndefined();expect(b.children().length).toBe(0)});it("Should return Autocomplete instance if called without arguments",function(){var b=$(document.createElement("input"));b.autocomplete({serviceUrl:"/test-dispose"});var a=b.autocomplete();expect(a instanceof $.Autocomplete).toBe(true)});it("Should set width to be greater than zero",function(){var b=$(document.createElement("input")),a,c;b.autocomplete({lookup:[{value:"Jamaica",data:"B"}]});b.val("Jam");b.width(100);a=b.autocomplete();a.onValueChange();c=$(a.suggestionsContainer).width();expect(c).toBeGreaterThan(0)});it("Should call beforeRender and pass container jQuery object",function(){var d=document.createElement("input"),b=$(d),a,e,c;b.autocomplete({lookup:[{value:"Jamaica",data:"B"}],beforeRender:function(f){c=this;e=f.length}});b.val("Jam");a=b.autocomplete();a.onValueChange();expect(c).toBe(d);expect(e).toBe(1)});it("Should trigger select when input value matches suggestion",function(){var c=$("<input />"),a,b=false;c.autocomplete({lookup:[{value:"Jamaica",data:"J"}],triggerSelectOnValidInput:true,onSelect:function(d){b=d.data}});c.val("Jamaica");a=c.autocomplete();a.onValueChange();expect(b).toBe("J")});it("Should NOT trigger select when input value matches suggestion",function(){var c=$("<input />"),a,b=null;c.autocomplete({lookup:[{value:"Jamaica",data:"J"}],triggerSelectOnValidInput:false,onSelect:function(d){b=d.data}});c.val("Jamaica");a=c.autocomplete();a.onValueChange();expect(b).toBeNull()});it("Should limit results for local request",function(){var c=$("<input />"),a,b=3;c.autocomplete({lookup:[{value:"Jamaica"},{value:"Jamaica"},{value:"Jamaica"},{value:"Jamaica"},{value:"Jamaica"}]});c.val("Jam");a=c.autocomplete();a.onValueChange();expect(a.suggestions.length).toBe(5);a.setOptions({lookupLimit:b});a.onValueChange();expect(a.suggestions.length).toBe(b)});it("Should display no suggestion notice when no matching results",function(){var a=document.createElement("input"),b={lookup:[{value:"Colombia",data:"Spain"}],showNoSuggestionNotice:true,noSuggestionNotice:"Sorry, no matching results"},c=new $.Autocomplete(a,b),d=$(c.suggestionsContainer);a.value="Jamaica";c.onValueChange();expect(c.visible).toBe(true);expect(c.selectedIndex).toBe(-1);expect(d.find(".autocomplete-no-suggestion").length).toBe(1);expect(d.find(".autocomplete-no-suggestion").text()).toBe("Sorry, no matching results")});it("Should call onHide and pass container jQuery object",function(){var d=document.createElement("input"),b=$(d),a,e,c;b.autocomplete({lookup:[{value:"Jamaica",data:"B"}],onHide:function(f){c=this;e=f.length}});b.val("Jam");a=b.autocomplete();a.onValueChange();b.val("Colombia");a.onValueChange();expect(c).toBe(d);expect(e).toBe(1)})});describe("When options.preserveInput is true",function(){var c=$("<input />"),a,b=null;beforeEach(function(){c.autocomplete({lookup:[{value:"Jamaica",data:"J"},{value:"Jamaica2",data:"J"},{value:"Jamaica3",data:"J"}],preserveInput:true,onSelect:function(d){b=d.data}});c.val("J");a=c.autocomplete()});afterEach(function(){a.dispose()});it("Should NOT change input value when item is selected",function(){a.onValueChange();a.select(0);expect(c.val()).toEqual("J")});it("Should NOT change input value when move down",function(){a.onValueChange();a.moveDown();expect(c.val()).toEqual("J")});it("Should NOT change input value when move up",function(){a.onValueChange();a.moveUp();expect(c.val()).toEqual("J")})});